pub fn initSortTable() [256]u8 {
        var table: [256]u8 = undefined;
        _ = &table;
        var i: usize = 0;
        _ = &i;
        while ((i < 256)) : (i = (i + 1)) {
            table[cp_cast_int(usize, i)] = @as(u8, @intCast(i));
        }
        table[cp_cast_int(usize, 91)] = 252;
        table[cp_cast_int(usize, 93)] = 253;
        table[cp_cast_int(usize, 47)] = 254;
        return table;
}
